BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO data_audit_log (table_name, record_id, action, new_data, scrape_proof, agent_id)
    VALUES (TG_TABLE_NAME, NEW.id::text, 'INSERT',
      row_to_json(NEW)::jsonb,
      json_build_object('scrape_html_hash', NEW.scrape_html_hash, 'scrape_timestamp', NEW.scrape_timestamp)::jsonb,
      'trigger_auto');
  ELSIF TG_OP = 'UPDATE' THEN
    INSERT INTO data_audit_log (table_name, record_id, action, old_data, new_data, scrape_proof, agent_id)
    VALUES (TG_TABLE_NAME, NEW.id::text, 'UPDATE',
      row_to_json(OLD)::jsonb,
      row_to_json(NEW)::jsonb,
      json_build_object('scrape_html_hash', NEW.scrape_html_hash, 'scrape_timestamp', NEW.scrape_timestamp)::jsonb,
      'trigger_auto');
  ELSIF TG_OP = 'DELETE' THEN
    INSERT INTO data_audit_log (table_name, record_id, action, old_data, agent_id)
    VALUES (TG_TABLE_NAME, OLD.id::text, 'DELETE', row_to_json(OLD)::jsonb, 'trigger_auto');
  END IF;
  RETURN COALESCE(NEW, OLD);
END;

DECLARE
  v_user_id uuid;
  v_revision bigint;
BEGIN
  -- No input changed: preserve the cursor and avoid a paid source send.
  IF TG_OP='UPDATE' AND OLD IS NOT DISTINCT FROM NEW THEN
    RETURN NEW;
  END IF;
  IF TG_TABLE_NAME = 'profiles' THEN
    v_user_id := NEW.id;
  ELSIF TG_OP = 'DELETE' THEN
    v_user_id := OLD.user_id;
  ELSE
    v_user_id := NEW.user_id;
  END IF;

  -- Cascading account deletion removes the profile before child triggers run.
  -- A cursor for a deleted user is unusable and would violate the cursor FK.
  IF v_user_id IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = v_user_id) THEN
    INSERT INTO public.daily_challenge_dashboard_revisions (user_id, revision, updated_at)
    VALUES (v_user_id, 1, clock_timestamp())
    ON CONFLICT (user_id) DO UPDATE
      SET revision = public.daily_challenge_dashboard_revisions.revision + 1,
          updated_at = EXCLUDED.updated_at
    RETURNING revision INTO v_revision;

    BEGIN
      PERFORM realtime.send(
        jsonb_build_object('revision', v_revision),
        'daily_mission_revision_changed',
        'daily-mission-revision:' || v_user_id::text,
        true
      );
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'Daily Mission revision broadcast failed: %', SQLERRM;
    END;

    IF TG_TABLE_NAME = 'user_daily_challenges' THEN
      IF TG_OP = 'UPDATE'
         AND OLD.completed IS NOT TRUE
         AND NEW.completed IS TRUE THEN
        BEGIN
          PERFORM realtime.send(
            jsonb_build_object(
              'id', NEW.id,
              'challengeId', NEW.challenge_id,
              'name', NEW.challenge_name_snapshot,
              'diamondReward', NEW.diamond_reward_snapshot
            ),
            'daily_mission_completed',
            'daily-mission-completion:' || v_user_id::text,
            true
          );
        EXCEPTION WHEN OTHERS THEN
          RAISE WARNING 'Daily Mission completion broadcast failed: %', SQLERRM;
        END;
      END IF;
    END IF;
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;

BEGIN
  RAISE EXCEPTION '% is append-only', TG_TABLE_NAME USING ERRCODE = '55000';
END

BEGIN
    IF NEW.scrape_html_hash IS NULL OR NEW.scrape_timestamp IS NULL THEN
        RAISE EXCEPTION 'CRITICAL VIOLATION: Cannot insert/update without scrape_html_hash and scrape_timestamp. (15-Layer Scrapling Web Scraper Integrity Standard)';
    END IF;

    -- 'manual_research'   = compiled from an official published schedule and
    --                       re-verified by hand. Attributed, but deliberately NOT
    --                       claiming to be a scrape.
    -- 'scraped_inferred'  = scraped, but extracted by regex/heuristic block parse
    --                       rather than a structured field. Lower confidence than
    --                       'scraped_verified' and must stay distinguishable from it.
    IF NEW.data_quality NOT IN ('scraped_verified', 'scraped_inferred', 'stale', 'expired', 'manual_research') THEN
        RAISE EXCEPTION 'CRITICAL VIOLATION: data_quality must be scraped_verified, scraped_inferred, stale, expired, or manual_research.';
    END IF;

    RETURN NEW;
END;

DECLARE b jsonb; a jsonb; identity_row jsonb; identity_key text; moved boolean;
BEGIN
 b:=CASE WHEN TG_OP='INSERT' THEN NULL ELSE public.fn_accounting_agreement_terms(TG_TABLE_NAME,to_jsonb(OLD)) END;
 a:=CASE WHEN TG_OP='DELETE' THEN NULL ELSE public.fn_accounting_agreement_terms(TG_TABLE_NAME,to_jsonb(NEW)) END;
 IF b IS NOT DISTINCT FROM a THEN RETURN COALESCE(NEW,OLD); END IF;
 identity_row:=COALESCE(b,a);
 identity_key:=CASE WHEN TG_TABLE_NAME='club_members' THEN identity_row->>'club_id'||':'||(identity_row->>'user_id') ELSE identity_row->>'id' END;
 moved:=TG_OP='UPDATE' AND (b->>'id' IS DISTINCT FROM a->>'id'
   OR b->>'club_id' IS DISTINCT FROM a->>'club_id' OR b->>'user_id' IS DISTINCT FROM a->>'user_id');
 INSERT INTO public.accounting_agreement_history(entity_type,entity_key,club_id,subject_user_id,event_type,actor_id,before_terms,after_terms)
 VALUES(TG_TABLE_NAME,identity_key,(identity_row->>'club_id')::uuid,(identity_row->>'user_id')::uuid,TG_OP,auth.uid(),b,CASE WHEN moved THEN NULL ELSE a END);
 -- A moved identity closes its original key and establishes the new key too.
 -- Both changes are observed in this transaction; neither is backdated.
 IF moved THEN
   identity_key:=CASE WHEN TG_TABLE_NAME='club_members' THEN a->>'club_id'||':'||(a->>'user_id') ELSE a->>'id' END;
   INSERT INTO public.accounting_agreement_history(entity_type,entity_key,club_id,subject_user_id,event_type,actor_id,before_terms,after_terms)
   VALUES(TG_TABLE_NAME,identity_key,(a->>'club_id')::uuid,(a->>'user_id')::uuid,'UPDATE',auth.uid(),NULL,a);
 END IF;
 RETURN COALESCE(NEW,OLD);
END

DECLARE old_source_id uuid;new_source_id uuid;hand uuid;
BEGIN
 IF TG_TABLE_NAME='rake_records' THEN
  old_source_id:=OLD.id;new_source_id:=NEW.id;
 ELSE
  IF TG_OP<>'INSERT' THEN old_source_id:=OLD.rake_record_id; END IF;
  IF TG_OP<>'DELETE' THEN new_source_id:=NEW.rake_record_id; END IF;
 END IF;
 -- The commission writer and every source mutation share the same hand key.
 -- A source edit which began before accrual must finish before it is frozen.
 FOR hand IN SELECT DISTINCT r.hand_id FROM public.rake_records r WHERE r.id IN(old_source_id,new_source_id) AND r.hand_id IS NOT NULL ORDER BY r.hand_id LOOP
  PERFORM pg_advisory_xact_lock(hashtextextended('accounting_cash_hand:'||hand::text,0));
 END LOOP;
 IF EXISTS(SELECT 1 FROM public.accounting_cash_accrual_batches WHERE rake_record_id IN(old_source_id,new_source_id)) THEN
  RAISE EXCEPTION 'recorded_cash_earning_source_is_immutable' USING ERRCODE='55000';
 END IF;
 RETURN COALESCE(NEW,OLD);
END

DECLARE a public.agents%ROWTYPE; credit public.credit_invoices%ROWTYPE;
BEGIN
 IF TG_TABLE_NAME='credit_invoices' THEN
   SELECT * INTO a FROM public.agents WHERE id=NEW.agent_id;
   INSERT INTO public.settlement_invoices(club_id,invoice_type,from_entity_type,from_entity_id,to_entity_type,to_entity_id,
    gross_amount,net_amount,deductions,breakdown,status,chips_transferred,due_at,source_credit_invoice_id,notes)
   VALUES(a.club_id,'transaction_receipt','club',a.club_id::text,'agent',a.user_id::text,
    NEW.debt_owed,NEW.debt_owed,0,jsonb_build_object('kind','credit_invoice','period_start',NEW.period_start,'period_end',NEW.period_end),
    'generated',false,NEW.due_date,NEW.id,CASE WHEN EXISTS(SELECT FROM public.agent_credit_weekly_basis b WHERE b.agent_id=NEW.agent_id AND b.period_end=NEW.period_end) THEN 'Agent Wallet Top-Up Invoice. Credit Line Minus Agent Wallet Before Rakeback.' ELSE 'Drawn Credit Invoice. This Amount Is Due From The Agent To The Club.' END);
 ELSIF TG_TABLE_NAME='credit_payments' THEN
   SELECT * INTO credit FROM public.credit_invoices WHERE id=NEW.invoice_id;
   SELECT * INTO a FROM public.agents WHERE id=credit.agent_id;
   INSERT INTO public.settlement_invoices(club_id,invoice_type,from_entity_type,from_entity_id,to_entity_type,to_entity_id,
    gross_amount,net_amount,deductions,breakdown,status,chips_transferred,transferred_at,source_credit_payment_id,notes)
   VALUES(a.club_id,'transaction_receipt','agent',a.user_id::text,'club',a.club_id::text,
    NEW.amount,NEW.amount,0,jsonb_build_object('kind','credit_payment','credit_invoice_id',NEW.invoice_id,'payment_method',NEW.payment_method,'transaction_id',NEW.transaction_id),
    'paid',NEW.payment_method='wallet',NEW.created_at,NEW.id,CASE WHEN EXISTS(SELECT FROM public.agent_credit_weekly_basis b WHERE b.agent_id=credit.agent_id AND b.period_end=credit.period_end) THEN 'Payment Restored The Agent Wallet Against The Referenced Top-Up Invoice.' ELSE 'Credit Payment Recorded Against The Referenced Invoice.' END);
 ELSE RAISE EXCEPTION 'unsupported_credit_document_source'; END IF;
 RETURN NEW;
END

DECLARE issued boolean;
BEGIN
 IF TG_TABLE_NAME='settlement_invoices' THEN
   IF TG_OP='UPDATE' AND public.fn_ca_launch_accounting_invoice_transition(to_jsonb(OLD),to_jsonb(NEW)) THEN RETURN NEW; END IF;
   IF (OLD.source_union_presettlement_id IS NOT NULL OR
       (TG_OP='UPDATE' AND NEW.source_union_presettlement_id IS NOT NULL)) AND (TG_OP='DELETE' OR
      (to_jsonb(NEW)-ARRAY['message_sent','message_sent_at']) IS DISTINCT FROM
      (to_jsonb(OLD)-ARRAY['message_sent','message_sent_at']))
   THEN RAISE EXCEPTION 'presettlement_receipt_is_immutable' USING ERRCODE='23514';END IF;
   IF OLD.invoice_type='credit_limit_change' AND (TG_OP='DELETE' OR
      (to_jsonb(NEW)-ARRAY['message_sent','message_sent_at']) IS DISTINCT FROM
      (to_jsonb(OLD)-ARRAY['message_sent','message_sent_at']))
   THEN RAISE EXCEPTION 'credit_change_document_is_immutable' USING ERRCODE='23514';END IF;
   IF OLD.invoice_type='accounting_correction' AND (TG_OP='DELETE' OR
      ROW(NEW.status,NEW.chips_transferred,NEW.transferred_at,NEW.due_at,NEW.chip_transfer_id,NEW.adjusts_invoice_id,
          NEW.source_credit_invoice_id,NEW.source_credit_payment_id,NEW.overdue_at,NEW.reminders_sent,NEW.last_reminder_at)
      IS DISTINCT FROM ROW(OLD.status,OLD.chips_transferred,OLD.transferred_at,OLD.due_at,OLD.chip_transfer_id,OLD.adjusts_invoice_id,
          OLD.source_credit_invoice_id,OLD.source_credit_payment_id,OLD.overdue_at,OLD.reminders_sent,OLD.last_reminder_at))
   THEN RAISE EXCEPTION 'correction_document_payment_claim_is_immutable' USING ERRCODE='23514';END IF;
   IF OLD.invoice_type='cashier_cashout' AND (TG_OP='DELETE' OR
      ROW(NEW.status,NEW.chips_transferred,NEW.transferred_at) IS DISTINCT FROM
      ROW(OLD.status,OLD.chips_transferred,OLD.transferred_at))
   THEN RAISE EXCEPTION 'cashier_document_phase_is_immutable' USING ERRCODE='23514';END IF;
   issued:=COALESCE(OLD.message_sent,false) OR EXISTS(SELECT 1 FROM public.accounting_invoice_deliveries WHERE invoice_id=OLD.id);
   IF issued AND (TG_OP='DELETE' OR
     ROW(NEW.club_id,NEW.period_id,NEW.invoice_type,NEW.invoice_number,NEW.from_entity_type,NEW.from_entity_id,
         NEW.to_entity_type,NEW.to_entity_id,NEW.gross_amount,NEW.net_amount,NEW.deductions,NEW.breakdown,
         NEW.due_at,NEW.notes,NEW.source_ledger_id,NEW.source_credit_invoice_id,NEW.source_credit_payment_id,NEW.created_at)
     IS DISTINCT FROM
     ROW(OLD.club_id,OLD.period_id,OLD.invoice_type,OLD.invoice_number,OLD.from_entity_type,OLD.from_entity_id,
         OLD.to_entity_type,OLD.to_entity_id,OLD.gross_amount,OLD.net_amount,OLD.deductions,OLD.breakdown,
         OLD.due_at,OLD.notes,OLD.source_ledger_id,OLD.source_credit_invoice_id,OLD.source_credit_payment_id,OLD.created_at)
     OR NEW.message_sent IS DISTINCT FROM true)
   THEN RAISE EXCEPTION 'issued_accounting_invoice_is_immutable' USING ERRCODE='23514'; END IF;
 ELSIF TG_TABLE_NAME='social_messages' THEN
   issued:=EXISTS(SELECT 1 FROM public.accounting_invoice_deliveries WHERE message_id=OLD.id);
   IF issued AND (TG_OP='DELETE' OR
      (to_jsonb(NEW)-ARRAY['read_at','updated_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['read_at','updated_at']))
   THEN RAISE EXCEPTION 'issued_accounting_message_is_immutable' USING ERRCODE='23514'; END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END

