DECLARE v_club uuid;
BEGIN
 IF TG_TABLE_NAME='profiles' THEN
  -- Only clubs where the person holds free chips have anything to return.
  FOR v_club IN
   SELECT s.club_id FROM (
    SELECT m.club_id FROM public.club_members m WHERE m.user_id=NEW.id
      AND coalesce(m.chip_balance,0)-coalesce(m.held_chips,0)-coalesce(m.locked_chips,0) > 0
    UNION
    SELECT a.club_id FROM public.agents a WHERE a.user_id=NEW.id
      AND coalesce(a.agent_wallet_balance,0) > 0
   ) s ORDER BY s.club_id
  LOOP
   PERFORM public.fn_ca_deleted_wallet_bank_return(v_club,NEW.id,'wallets');
  END LOOP;
  RETURN NEW;
 END IF;
 -- Only the trusted owning stage may hold a pass-through credit until its
 -- original transfer and final net-balance assertions have completed. Each
 -- stage flushes these exact pinned recipients before returning success.
 -- A browser-set GUC or an unrelated row never defers. Since 20261022 weekly
 -- commission is credited to agent wallets, so the commission stage's pinned
 -- agent-wallet recipients defer exactly as its member wallets did.
 IF TG_TABLE_NAME='agents' AND public.fn_caller_is_engine() IS TRUE
  AND nullif(current_setting('app.accounting_routing_context',true),'') IS NOT NULL
  AND current_setting('app.deleted_wallet_routing_stage',true)='commission'
  AND to_regclass('pg_temp._routed_nodes') IS NOT NULL THEN
  IF EXISTS(SELECT FROM pg_temp._routed_nodes n WHERE n.club_id=NEW.club_id AND n.user_id=NEW.user_id) THEN RETURN NEW; END IF;
 END IF;
 IF TG_TABLE_NAME='club_members' AND public.fn_caller_is_engine() IS TRUE
  AND nullif(current_setting('app.accounting_routing_context',true),'') IS NOT NULL THEN
  IF current_setting('app.deleted_wallet_routing_stage',true)='commission'
   AND to_regclass('pg_temp._routed_nodes') IS NOT NULL THEN
   IF EXISTS(SELECT FROM pg_temp._routed_nodes n WHERE n.club_id=NEW.club_id AND n.user_id=NEW.user_id) THEN RETURN NEW; END IF;
  ELSIF current_setting('app.deleted_wallet_routing_stage',true)='rakeback'
   AND to_regclass('pg_temp._routed_player_wallets') IS NOT NULL THEN
   IF EXISTS(SELECT FROM pg_temp._routed_player_wallets w WHERE w.club_id=NEW.club_id AND w.user_id=NEW.user_id) THEN RETURN NEW; END IF;
  END IF;
 END IF;
 IF EXISTS (SELECT 1 FROM public.profiles WHERE id=NEW.user_id AND status='deleted') THEN
  PERFORM public.fn_ca_deleted_wallet_bank_return(NEW.club_id,NEW.user_id,CASE WHEN TG_TABLE_NAME='agents' THEN 'agent_wallet' ELSE 'player_wallet' END);
 END IF;
 RETURN NEW;
END;

DECLARE
    v_sql text;
BEGIN
    BEGIN
        v_sql := format(
            'INSERT INTO public.%I (op, old_row, new_row) VALUES ($1, $2, $3)',
            TG_TABLE_NAME || '_history');
        IF TG_OP = 'INSERT' THEN
            EXECUTE v_sql USING TG_OP, NULL::jsonb, to_jsonb(NEW);
        ELSIF TG_OP = 'DELETE' THEN
            EXECUTE v_sql USING TG_OP, to_jsonb(OLD), NULL::jsonb;
        ELSE
            EXECUTE v_sql USING TG_OP, to_jsonb(OLD), to_jsonb(NEW);
        END IF;
    EXCEPTION WHEN OTHERS THEN
        PERFORM public.fn_ca_diamond_incident(
            'D21:catalog_history_write_failed', 'warning', NULL, NULL,
            'fn_ca_diamond_catalog_history',
            jsonb_build_object('table', TG_TABLE_NAME, 'op', TG_OP,
                               'sqlstate', SQLSTATE, 'sqlerrm', SQLERRM));
    END;
    RETURN NULL;
END;

BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.clubs c WHERE c.id=NEW.club_id AND c.asset='diamonds') THEN RETURN NEW; END IF;
 NEW.name:=public.fn_ca_diamond_guarantee_copy(NEW.name);
 NEW.description:=public.fn_ca_diamond_guarantee_copy(NEW.description);
 IF TG_TABLE_NAME='tournaments' THEN
  NEW.short_description:=public.fn_ca_diamond_guarantee_copy(NEW.short_description);
 ELSE
  NEW.config:=NEW.config
   || CASE WHEN jsonb_typeof(NEW.config->'name')='string' THEN jsonb_build_object('name',public.fn_ca_diamond_guarantee_copy(NEW.config->>'name')) ELSE '{}'::jsonb END
   || CASE WHEN jsonb_typeof(NEW.config->'shortDescription')='string' THEN jsonb_build_object('shortDescription',public.fn_ca_diamond_guarantee_copy(NEW.config->>'shortDescription')) ELSE '{}'::jsonb END
   || CASE WHEN jsonb_typeof(NEW.config->'satelliteTargetName')='string' THEN jsonb_build_object('satelliteTargetName',public.fn_ca_diamond_guarantee_copy(NEW.config->>'satelliteTargetName')) ELSE '{}'::jsonb END;
 END IF;
 RETURN NEW;
END

BEGIN
  RAISE EXCEPTION '% is append-only', TG_TABLE_NAME USING ERRCODE = '55000';
END

DECLARE
  v_asset text;
BEGIN
  -- The index must not resurrect a retained hand after its count was archived.
  -- Keep the shared asset function unchanged for every other relation.
  IF TG_TABLE_SCHEMA='public' AND TG_TABLE_NAME='ca_hand_player_idx' THEN
    PERFORM 1 FROM public.hand_history WHERE id=NEW.hand_id FOR KEY SHARE;
    IF NOT FOUND THEN RETURN NULL; END IF;
  END IF;
  -- The club whose table the hand was dealt at decides, the same test the
  -- post-commit projection makes for v_diamond; if the table is gone, the
  -- tournament's club. A hand that cannot be found keeps what the writer
  -- gave, which is the column default: every writer reads the hand from
  -- hand_history in the same statement, so that does not arise.
  SELECT c.asset INTO v_asset
    FROM public.hand_history h
    LEFT JOIN public.tables t ON t.id = h.table_id
    LEFT JOIN public.tournaments tr ON tr.id = h.tournament_id
    JOIN public.clubs c ON c.id = coalesce(t.club_id, tr.club_id)
   WHERE h.id = NEW.hand_id;
  IF FOUND THEN
    NEW.asset := CASE WHEN v_asset = 'diamonds' THEN 'diamonds' ELSE 'chips' END;
  END IF;
  RETURN NEW;
END

DECLARE cut timestamptz;
BEGIN
 cut:=public.fn_ca_launch_accounting_cutoff('club',NEW.club_id);
 IF cut IS NULL THEN RETURN NEW; END IF;
 -- A delayed or backdated request cannot create an old obligation after launch.
 IF TG_OP='INSERT' AND (NEW.created_at IS NULL OR NEW.created_at<cut) THEN
  RAISE EXCEPTION 'LAUNCH_PREVIOUS_CASHIER_REQUEST_IS_WAIVED' USING ERRCODE='55000';
 END IF;
 IF TG_OP='UPDATE' AND (OLD.created_at IS NULL OR OLD.created_at<cut)
   AND (NEW.status IS DISTINCT FROM OLD.status OR NEW.created_at IS DISTINCT FROM OLD.created_at
     OR NEW.club_id IS DISTINCT FROM OLD.club_id) THEN
  RAISE EXCEPTION 'LAUNCH_PREVIOUS_CASHIER_REQUEST_IS_WAIVED' USING ERRCODE='55000';
 END IF;
 RETURN NEW;
END

BEGIN
  -- Nested, not AND: an origin session (every real write) reads one setting
  -- and leaves; the cluster identity is read only in replica mode.
  IF current_setting('session_replication_role') <> 'replica' THEN
    RETURN NULL;
  END IF;
  IF public.fn_ca_is_protected_cluster() THEN
    RAISE EXCEPTION 'REFUSED: % on public.% under session_replication_role = replica',
      TG_OP, TG_TABLE_NAME
      USING ERRCODE = '42501',
            DETAIL  = 'Replica mode switches off every ordinary trigger on this table: the ledger tally, the commit-time ledger invariant, the seat exit log and the inventory observer. On 2026-10-06 15:33 UTC that is how 43 cash seats holding 14,081.45 chips were vacated with no cashout and no burn.',
            HINT    = 'Move chips through their door in an origin session. The door writes the balance and its chip_ledger leg in one transaction.';
  END IF;
  RETURN NULL;
END

DECLARE v_scope text := coalesce(TG_ARGV[0],'account'); v_tourney uuid;
BEGIN
  IF TG_TABLE_NAME='table_seats' THEN
    SELECT tournament_id INTO v_tourney FROM public.tables WHERE id=NEW.table_id;
    v_scope := CASE WHEN v_tourney IS NULL THEN 'cash' ELSE 'tournaments' END;
  END IF;
  PERFORM public.fn_ca_assert_player_action(NEW.user_id,v_scope,TG_TABLE_NAME);
  RETURN NEW;
EXCEPTION WHEN insufficient_privilege THEN RAISE;
  WHEN OTHERS THEN RETURN NEW;
END

DECLARE v_user uuid;
BEGIN
  v_user := (to_jsonb(NEW)->>TG_ARGV[0])::uuid;
  IF TG_OP='UPDATE' AND (to_jsonb(NEW)->>'is_deleted')='true' THEN RETURN NEW; END IF;
  PERFORM public.fn_ca_assert_player_action(v_user,'social',TG_TABLE_NAME);
  RETURN NEW;
END

BEGIN
  IF TG_TABLE_NAME='chip_transactions' THEN
    IF NEW.transaction_type IN ('transfer','peer_transfer','user_transfer') AND NEW.amount>0 THEN
      PERFORM public.fn_ca_assert_player_action(NEW.from_user_id,'transfers',TG_TABLE_NAME);
    END IF;
  ELSIF TG_TABLE_NAME='wallet_transactions' THEN
    IF NEW.type='debit' AND NEW.category='transfer' AND NEW.amount>0 THEN
      PERFORM public.fn_ca_assert_player_action(NEW.user_id,'transfers',TG_TABLE_NAME);
    END IF;
  ELSIF NEW.amount<0 AND NEW.source IN ('wallet_transfer','wallet_diamond_transfer','stream_gift') THEN
    PERFORM public.fn_ca_assert_player_action(NEW.user_id,'transfers',TG_TABLE_NAME);
  END IF;
  RETURN NEW;
END

DECLARE
  v_club_id uuid;
  v_user_id uuid;
  v_automated boolean := false;
  v_is_horse boolean := false;
  v_refusal text;
  v_tournament_seat boolean := false;
BEGIN
  IF TG_TABLE_NAME = 'club_members' THEN
    v_club_id := NEW.club_id;
    v_user_id := NEW.user_id;
    v_automated := COALESCE(NEW.is_bot, false);
  ELSIF TG_TABLE_NAME = 'agents' THEN
    v_club_id := NEW.club_id;
    v_user_id := NEW.user_id;
  ELSIF TG_TABLE_NAME = 'table_seats' THEN
    -- A historical/departed seat remains immutable evidence. Only a live seat
    -- can put an automated player back onto a user-created club table.
    IF NEW.left_at IS NOT NULL THEN RETURN NEW; END IF;
    SELECT t.club_id, t.tournament_id IS NOT NULL INTO v_club_id, v_tournament_seat FROM public.tables t WHERE t.id = NEW.table_id;
    v_user_id := NEW.user_id;
  ELSIF TG_TABLE_NAME = 'tournament_players' THEN
    SELECT t.club_id INTO v_club_id
      FROM public.tournaments t WHERE t.id = NEW.tournament_id;
    v_user_id := NEW.user_id;
  ELSE
    RAISE EXCEPTION 'Unsupported Automated-Club Guard Table: %', TG_TABLE_NAME;
  END IF;

  v_is_horse := COALESCE(
    (SELECT p.is_horse FROM public.profiles p WHERE p.id = v_user_id), false
  );
  v_automated := v_automated OR v_is_horse;

  IF v_automated AND NOT public.fn_ca_house_board_allows_automation(v_club_id) THEN
    RAISE EXCEPTION 'AUTOMATED_PLAYER_HOUSE_BOARD_ONLY: Automated Players Cannot Enter A User-Created Club'
      USING ERRCODE = '42501';
  END IF;

  -- HORSES BELONG TO ONE ASSIGNED CLUB (20261102141229). Agents rows follow
  -- their membership; a departed membership update (lifecycle) is judged by
  -- fn_guard_membership_lifecycle_write instead.
  -- A tournament seat belongs to an entry that was admitted when it was made;
  -- the event seats, moves and re-seats it in any phase (20261102191900).
  IF v_is_horse AND TG_TABLE_NAME <> 'agents' AND NOT v_tournament_seat THEN
    v_refusal := public.fn_ca_horse_club_refusal(
      v_user_id, v_club_id,
      CASE WHEN TG_TABLE_NAME = 'tournament_players' THEN NEW.club_id END,
      TG_TABLE_NAME = 'club_members');
    IF v_refusal IS NOT NULL THEN
      RAISE EXCEPTION '%', v_refusal USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END;

BEGIN
  IF EXISTS (SELECT 1 FROM public.clubs WHERE id=NEW.club_id AND asset='diamonds') THEN
    RAISE EXCEPTION 'Diamond Rake Is Never A Chip Rake Record' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END

DECLARE
  o jsonb := CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE to_jsonb(OLD) END;
  n jsonb := CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE to_jsonb(NEW) END;
  k_old text; k_new text;
  v_old numeric := 0; v_new numeric := 0;
BEGIN
  CASE TG_TABLE_NAME
    WHEN 'club_members' THEN
      IF o IS NOT NULL THEN
        k_old := 'player_wallet:' || COALESCE(o ->> 'user_id', 'null') || ':' || COALESCE(o ->> 'club_id', 'null');
        v_old := COALESCE((o ->> 'chip_balance')::numeric, 0);
      END IF;
      IF n IS NOT NULL THEN
        k_new := 'player_wallet:' || COALESCE(n ->> 'user_id', 'null') || ':' || COALESCE(n ->> 'club_id', 'null');
        v_new := COALESCE((n ->> 'chip_balance')::numeric, 0);
      END IF;
    WHEN 'clubs' THEN
      IF o IS NOT NULL THEN
        k_old := 'club_treasury:' || (o ->> 'id');
        v_old := COALESCE((o ->> 'chip_treasury')::numeric, 0) + COALESCE((o ->> 'chip_pool')::numeric, 0);
      END IF;
      IF n IS NOT NULL THEN
        k_new := 'club_treasury:' || (n ->> 'id');
        v_new := COALESCE((n ->> 'chip_treasury')::numeric, 0) + COALESCE((n ->> 'chip_pool')::numeric, 0);
      END IF;
    WHEN 'table_seats' THEN
      /* A seat is on the felt while it is occupied (left_at IS NULL) and its
         table is a cash chip table. A vacated seat's stack has left the felt
         whether or not the row zeroes it, which is exactly what
         fn_log_seat_stack_exit records and what a cash-out leg explains. */
      k_old := 'table_stack'; k_new := 'table_stack';
      IF o IS NOT NULL AND (o ->> 'left_at') IS NULL
         AND public.fn_ca_felt_counts_table((o ->> 'table_id')::uuid) THEN
        v_old := COALESCE((o ->> 'stack')::numeric, 0);
      END IF;
      IF n IS NOT NULL AND (n ->> 'left_at') IS NULL
         AND public.fn_ca_felt_counts_table((n ->> 'table_id')::uuid) THEN
        v_new := COALESCE((n ->> 'stack')::numeric, 0);
      END IF;
    WHEN 'table_pending_addons' THEN
      /* The add-on's leg lands at request time; the chips wait here until the
         hand ends. They are on the felt the whole time (fn_ca_supply_snapshot
         pending_addons, 2026-09-12), so resolving one is not a movement. */
      k_old := 'table_stack'; k_new := 'table_stack';
      IF o IS NOT NULL AND (o ->> 'resolved_at') IS NULL
         AND public.fn_ca_felt_counts_table((o ->> 'table_id')::uuid) THEN
        v_old := COALESCE((o ->> 'amount')::numeric, 0);
      END IF;
      IF n IS NOT NULL AND (n ->> 'resolved_at') IS NULL
         AND public.fn_ca_felt_counts_table((n ->> 'table_id')::uuid) THEN
        v_new := COALESCE((n ->> 'amount')::numeric, 0);
      END IF;
    WHEN 'hand_atomic_commits' THEN
      /* THE FEES A HAND TAKES OFF ITS SEATS STAY ON THE FELT UNTIL THEIR LEGS
         ARE POSTED (20261001231409). The accepted-hand transaction moves the
         seats by inflow - rake - bbj and writes no leg for the fees. Their
         legs - table_stack -> union_wallet or chip_retirement for the rake,
         table_stack -> bbj_pool for the drop, the insurance bank's leg for the
         inflow - are posted by fn_ca_process_hand_post_commit_obligations in
         a LATER transaction, under the club wallet, VIP carry and pool locks
         the commit path must not wait on. So the hand's own receipt carries
         the fees as felt from the moment its envelope is stored until the
         moment that envelope completes - in the same transaction that posts
         the legs. Each transaction balances on its own, and a hand whose
         second half has not run yet reads as fees still on the felt, never as
         chips that vanished. Scoped exactly like the seat: the cash chip felt. */
      k_old := 'table_stack'; k_new := 'table_stack';
      IF o IS NOT NULL AND (o ->> 'post_commit_payload') IS NOT NULL
         AND (o ->> 'post_commit_completed_at') IS NULL
         AND public.fn_ca_felt_counts_table((o ->> 'table_id')::uuid) THEN
        v_old := COALESCE((o -> 'stack_result' ->> 'rake')::numeric, 0)
               + COALESCE((o -> 'stack_result' ->> 'bbj')::numeric, 0)
               - COALESCE((o -> 'stack_result' ->> 'inflow')::numeric, 0);
      END IF;
      IF n IS NOT NULL AND (n ->> 'post_commit_payload') IS NOT NULL
         AND (n ->> 'post_commit_completed_at') IS NULL
         AND public.fn_ca_felt_counts_table((n ->> 'table_id')::uuid) THEN
        v_new := COALESCE((n -> 'stack_result' ->> 'rake')::numeric, 0)
               + COALESCE((n -> 'stack_result' ->> 'bbj')::numeric, 0)
               - COALESCE((n -> 'stack_result' ->> 'inflow')::numeric, 0);
      END IF;
    WHEN 'union_wallets' THEN
      /* Two accounts on one row: the bank (chip_balance) and the five
         operating wallets, both keyed by the union. */
      IF o IS NOT NULL THEN
        PERFORM public.fn_ca_ledger_tally_add('union_bank:' || (o ->> 'union_id'), 'b',
                  -COALESCE((o ->> 'chip_balance')::numeric, 0));
        k_old := 'union_wallet:' || (o ->> 'union_id');
        v_old := COALESCE((o ->> 'rake_wallet')::numeric, 0) + COALESCE((o ->> 'bbj_wallet')::numeric, 0)
               + COALESCE((o ->> 'promo_wallet')::numeric, 0) + COALESCE((o ->> 'insurance_wallet')::numeric, 0)
               + COALESCE((o ->> 'spin_reserve_wallet')::numeric, 0);
      END IF;
      IF n IS NOT NULL THEN
        PERFORM public.fn_ca_ledger_tally_add('union_bank:' || (n ->> 'union_id'), 'b',
                  COALESCE((n ->> 'chip_balance')::numeric, 0));
        k_new := 'union_wallet:' || (n ->> 'union_id');
        v_new := COALESCE((n ->> 'rake_wallet')::numeric, 0) + COALESCE((n ->> 'bbj_wallet')::numeric, 0)
               + COALESCE((n ->> 'promo_wallet')::numeric, 0) + COALESCE((n ->> 'insurance_wallet')::numeric, 0)
               + COALESCE((n ->> 'spin_reserve_wallet')::numeric, 0);
      END IF;
    WHEN 'bbj_pools' THEN
      IF o IS NOT NULL THEN
        k_old := 'bbj_pool:' || (o ->> 'id');
        v_old := COALESCE((o ->> 'main_balance')::numeric, 0) + COALESCE((o ->> 'backup_balance')::numeric, 0)
               + COALESCE((o ->> 'promo_balance')::numeric, 0);
      END IF;
      IF n IS NOT NULL THEN
        k_new := 'bbj_pool:' || (n ->> 'id');
        v_new := COALESCE((n ->> 'main_balance')::numeric, 0) + COALESCE((n ->> 'backup_balance')::numeric, 0)
               + COALESCE((n ->> 'promo_balance')::numeric, 0);
      END IF;
    ELSE
      RAISE EXCEPTION 'fn_ca_tally_balance_move is not configured for %', TG_TABLE_NAME;
  END CASE;

  /* A row that changes account (a seat changing table, a membership changing
     club) leaves one account and arrives in another; both sides are counted. */
  IF k_old IS NOT NULL AND k_new IS NOT NULL AND k_old = k_new THEN
    PERFORM public.fn_ca_ledger_tally_add(k_new, 'b', v_new - v_old);
  ELSE
    IF k_old IS NOT NULL THEN PERFORM public.fn_ca_ledger_tally_add(k_old, 'b', -v_old); END IF;
    IF k_new IS NOT NULL THEN PERFORM public.fn_ca_ledger_tally_add(k_new, 'b', v_new); END IF;
  END IF;
  RETURN NULL;
END;

