DECLARE
  v_allowed boolean := COALESCE(current_setting('app.deep_stack_teardown', true), '') = 'on';
  v_query   text;
BEGIN
  SELECT a.query INTO v_query
    FROM pg_stat_activity a WHERE a.pid = pg_backend_pid();

  INSERT INTO public.deep_stack_delete_attempts
    (source_table, allowed, db_user, db_role, application, client_addr, backend_pid, running_query, old_row)
  VALUES
    (TG_TABLE_NAME, v_allowed, session_user, current_user,
     current_setting('application_name', true), host(COALESCE(inet_client_addr(), '0.0.0.0'::inet)),
     pg_backend_pid(), left(COALESCE(v_query, ''), 4000), to_jsonb(OLD));

  IF NOT v_allowed THEN
    RAISE EXCEPTION
      'DEEP_STACK_PROTECTED: this row belongs to Deep Stack Society (club 11192) and is not deletable'
      USING ERRCODE = '42501',
            HINT = 'The whole club was deleted once with no audit trail. Set app.deep_stack_teardown = ''on'' for your transaction if you really mean it.';
  END IF;

  RETURN OLD;
END;

BEGIN
  IF NULLIF(current_setting('app.ledger_maintenance', true), '') IS NOT NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  IF TG_TABLE_NAME = 'crash_rounds' THEN
    IF TG_OP = 'UPDATE' AND OLD.status = 'open' THEN
      IF NEW.minimum_payout_chips IS DISTINCT FROM OLD.minimum_payout_chips THEN
        RAISE EXCEPTION 'The Bonus Minimum Is Fixed When The Round Starts' USING ERRCODE='integrity_constraint_violation';
      END IF;
      -- A live round settles once, through fn_crash_decide, and nothing it sealed moves.
      IF NEW.status IN ('cashed', 'crashed')
         AND (to_jsonb(NEW) - ARRAY['status', 'settled_at', 'settled_by', 'elapsed_ms', 'cashout_cents', 'payout_chips',
                                    'pool_chips_minted_after', 'pool_chips_paid_after', 'member_chips_after'])
           = (to_jsonb(OLD) - ARRAY['status', 'settled_at', 'settled_by', 'elapsed_ms', 'cashout_cents', 'payout_chips',
                                    'pool_chips_minted_after', 'pool_chips_paid_after', 'member_chips_after']) THEN
        RETURN NEW;
      END IF;
      RAISE EXCEPTION 'A Sealed Crash Round Cannot Be Rewritten' USING ERRCODE='integrity_constraint_violation';
    END IF;
  ELSIF TG_TABLE_NAME = 'diamond_game_commits' THEN
    IF TG_OP = 'UPDATE' THEN
      -- A ticket is spent once: consumed_by goes from nothing to its round, and nothing else moves.
      IF OLD.consumed_by IS NULL AND NEW.consumed_by IS NOT NULL
         AND (to_jsonb(NEW) - 'consumed_by') = (to_jsonb(OLD) - 'consumed_by') THEN
        RETURN NEW;
      END IF;
    ELSIF OLD.consumed_by IS NULL AND OLD.expires_at < now() THEN
      -- The one sweep fn_diamond_game_commit runs: a ticket nobody used, after it expired.
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'A Sealed Game Ticket Cannot Be Rewritten' USING ERRCODE='integrity_constraint_violation';
  END IF;
  RAISE EXCEPTION '% is append-only: a settled round is a fact and is never edited or deleted', TG_TABLE_NAME
    USING ERRCODE = 'integrity_constraint_violation';
END

DECLARE host uuid; cover numeric; old_cover numeric; held numeric;
BEGIN
 IF TG_TABLE_NAME='clubs' THEN
  host:=NEW.id; cover:=GREATEST(COALESCE(NEW.promo_balance,0),0)+GREATEST(COALESCE(NEW.chip_treasury,0),0);
  old_cover:=GREATEST(COALESCE(OLD.promo_balance,0),0)+GREATEST(COALESCE(OLD.chip_treasury,0),0);
 ELSE
  host:=NEW.union_id; cover:=GREATEST(COALESCE(NEW.promo_wallet,0),0)+GREATEST(COALESCE(NEW.chip_balance,0),0);
  old_cover:=GREATEST(COALESCE(OLD.promo_wallet,0),0)+GREATEST(COALESCE(OLD.chip_balance,0),0);
 END IF;
 IF cover>=old_cover THEN RETURN NEW; END IF;
 SELECT COALESCE(sum(reserved_chips),0) INTO held FROM public.diamond_game_pools WHERE host_id=host;
 IF cover<held THEN RAISE EXCEPTION 'These Chips Are Reserved For Open Game Rounds'; END IF;
 RETURN NEW;
END

