 -- let an already-started writer cross cancellation's exclusive lane.
 SELECT tournament_id INTO t FROM public.tables WHERE id=NEW.table_id;
 IF t IS NOT NULL THEN
 IF NOT pg_try_advisory_xact_lock_shared(hashtextextended('ca:tournament-terminal-settlement:v1',0))
 OR NOT pg_try_advisory_xact_lock_shared(hashtextextended('ca:tournament-terminal-settlement:v1:'||t::text,0)) THEN
 RAISE EXCEPTION 'F06_RETRY_CANONICAL_LANE' USING ERRCODE='55P03'; END IF;
 IF EXISTS(SELECT 1 FROM smarter_private.f06_prepared_hand_cancellations
 WHERE table_id=NEW.table_id AND hand_number=NEW.hand_number)
 OR EXISTS(SELECT 1 FROM smarter_private.f06_no_start_continuations
 WHERE table_id=NEW.table_id AND hand_number=NEW.hand_number) THEN
 RAISE EXCEPTION 'F06_CANCELLED_PREPARATION_FENCED' USING ERRCODE='55000'; END IF;
 END IF;
 RETURN NEW;
END

DECLARE b uuid;
BEGIN
 IF TG_TABLE_NAME='f06_operations' THEN
 IF NEW.manifest IS NOT DISTINCT FROM OLD.manifest THEN RETURN NEW; END IF;
 b:=NEW.break_id;
 ELSE
 SELECT break_id INTO b FROM smarter_private.f06_attempts WHERE request_id=NEW.request_id;
 END IF;
 PERFORM smarter_private.f06_assert_movement(b);
 RETURN NEW;
END

DECLARE v_row smarter_private.tournament_terminal_requests%ROWTYPE; v_id uuid;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM smarter_private.tournament_terminal_requests WHERE tournament_id=NEW.tournament_id) THEN RETURN NEW; END IF;
  BEGIN v_id:=NULLIF(current_setting('app.tournament_terminal_request_id',true),'')::uuid;
  EXCEPTION WHEN invalid_text_representation THEN v_id:=NULL; END;
  SELECT * INTO v_row FROM smarter_private.tournament_terminal_requests
   WHERE request_id=v_id AND tournament_id=NEW.tournament_id AND phase='prepared';
  IF NOT FOUND THEN RAISE EXCEPTION 'terminal receipt requires its open original request' USING ERRCODE='55000'; END IF;
  IF TG_TABLE_NAME='tournament_terminal_settlements' THEN
    IF v_row.original_request->>'kind' NOT IN ('places','legacy_deal','proposal_deal')
       OR NEW.settlement_mode IS DISTINCT FROM (CASE WHEN v_row.original_request->>'kind'='places' THEN 'places' ELSE 'final_table_deal' END)
       OR (v_row.original_request->>'observedWinnerId' IS NOT NULL AND NEW.winner_id IS DISTINCT FROM (v_row.original_request->>'observedWinnerId')::uuid)
       OR (v_row.original_request->>'kind'='proposal_deal' AND
          (current_setting('app.tournament_deal_proposal_id',true) IS DISTINCT FROM v_row.original_request->>'proposalId'
           OR current_setting('app.tournament_deal_proposal_revision',true) IS DISTINCT FROM v_row.original_request->>'revision')) THEN
      RAISE EXCEPTION 'terminal receipt differs from original request' USING ERRCODE='55000';
    END IF;
  ELSIF TG_TABLE_NAME='tournament_satellite_settlements' THEN
    IF v_row.original_request->>'kind'='satellite' THEN
      IF NEW.winner_id IS DISTINCT FROM (v_row.original_request->>'observedWinnerId')::uuid THEN
        RAISE EXCEPTION 'satellite winner differs from original request' USING ERRCODE='55000';
      END IF;
    ELSIF v_row.original_request->>'kind'='satellite_qualifiers' THEN
      IF to_jsonb(NEW.qualifier_ids) IS DISTINCT FROM v_row.original_request->'qualifierIds' OR NEW.winner_id IS NOT NULL THEN
        RAISE EXCEPTION 'satellite qualifiers differ from original request' USING ERRCODE='55000';
      END IF;
    ELSE RAISE EXCEPTION 'satellite receipt has wrong original request kind' USING ERRCODE='55000'; END IF;
  END IF;
  RETURN NEW;
END

DECLARE tab uuid; event_id uuid;
BEGIN
 -- A move cannot escape the old archived identity by changing its table ID.
 FOR tab IN SELECT DISTINCT x FROM unnest(ARRAY[(to_jsonb(NEW)->>'table_id')::uuid,(to_jsonb(OLD)->>'table_id')::uuid]) x WHERE x IS NOT NULL ORDER BY x LOOP
  SELECT tournament_id INTO event_id FROM public.tables WHERE id=tab;
  IF event_id IS NULL THEN CONTINUE;END IF;
  IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' THEN
   RAISE EXCEPTION 'TOURNAMENT_ARCHIVE_WRITER_READ_COMMITTED_REQUIRED' USING ERRCODE='55000';END IF;
  IF NOT EXISTS(SELECT 1 FROM smarter_private.tournament_abort_targets a WHERE a.tournament_id=event_id) THEN CONTINUE;END IF;
  PERFORM 1 FROM public.tables WHERE id=tab FOR UPDATE;
  -- Separate SPI statement after the lock obtains a fresh READ COMMITTED
  -- snapshot, including the cancellation that committed while we waited.
  IF EXISTS(SELECT 1 FROM smarter_private.tournament_abort_hand_dispositions d WHERE d.table_id=tab) THEN
   RAISE EXCEPTION 'TOURNAMENT_HAND_ARCHIVED_BY_OPERATOR' USING ERRCODE='55000';END IF;
 END LOOP;
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;
END

DECLARE
  v_owner uuid;
BEGIN
  IF TG_TABLE_NAME = 'profiles' THEN
    v_owner := NEW.id;
  ELSE
    v_owner := NEW.user_id;
  END IF;

  IF NEW.equipped_frame IS DISTINCT FROM (CASE WHEN TG_OP = 'UPDATE' THEN OLD.equipped_frame ELSE NULL END)
     AND NEW.equipped_frame IS NOT NULL THEN
    IF NOT public.sp_cosmetic_is_owned(v_owner, NEW.equipped_frame, 'frame') THEN
      RAISE EXCEPTION
        'equipped_frame % is not owned by % (or is not a known frame)',
        NEW.equipped_frame, v_owner
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF NEW.equipped_aura IS DISTINCT FROM (CASE WHEN TG_OP = 'UPDATE' THEN OLD.equipped_aura ELSE NULL END)
     AND NEW.equipped_aura IS NOT NULL THEN
    IF NOT public.sp_cosmetic_is_owned(v_owner, NEW.equipped_aura, 'aura') THEN
      RAISE EXCEPTION
        'equipped_aura % is not owned by % (or is not a known aura)',
        NEW.equipped_aura, v_owner
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  RETURN NEW;
END;

DECLARE
  v_tournament_id uuid;
  v_user_id uuid;
  v_parent_status text;
BEGIN
  IF TG_TABLE_NAME = 'table_seats' THEN
    IF TG_OP = 'DELETE' OR NEW.left_at IS NOT NULL OR NEW.user_id IS NULL THEN
      RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
    END IF;
    SELECT t.tournament_id INTO v_tournament_id
      FROM public.tables t
     WHERE t.id = NEW.table_id;
    v_user_id := NEW.user_id;
  ELSE
    IF TG_OP = 'INSERT' THEN
      RETURN NEW;
    END IF;
    v_tournament_id := OLD.tournament_id;
    v_user_id := OLD.user_id;
  END IF;

  IF v_tournament_id IS NOT NULL THEN
    SELECT t.status::text INTO v_parent_status
      FROM public.tournaments t
     WHERE t.id = v_tournament_id;
  END IF;

  /* Terminal cleanup may intentionally close the roster and seats in
     separate idempotent requests.  The invariant is strict while the event
     is joinable or playable; finished/cancelled tables are separately barred
     from acquiring new live seats and may drain without being wedged. */
  IF v_tournament_id IS NOT NULL
     AND upper(COALESCE(v_parent_status, '')) IN ('REGISTERING', 'RUNNING')
     AND EXISTS (
       SELECT 1
         FROM public.table_seats s
         JOIN public.tables t ON t.id = s.table_id
        WHERE t.tournament_id = v_tournament_id
          AND s.user_id = v_user_id
          AND s.left_at IS NULL
     )
     AND NOT EXISTS (
       SELECT 1
         FROM public.tournament_players p
        WHERE p.tournament_id = v_tournament_id
          AND p.user_id = v_user_id
          AND p.status IN ('registered', 'playing')
     ) THEN
    RAISE EXCEPTION
      'TOURNAMENT_SEAT_ROSTER_REQUIRED: live seat user % has no active roster in tournament % at commit',
      v_user_id, v_tournament_id
      USING ERRCODE = '23514';
  END IF;

  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;

DECLARE
  v_tournament_id uuid;
  v_flag text;
  v_result jsonb;
  v_state text;
  v_message text;
  v_attempt integer := 0;
BEGIN
  IF TG_TABLE_NAME = 'tournaments' THEN
    v_tournament_id := NEW.id;
  ELSE
    v_tournament_id := NEW.tournament_id;
  END IF;
  IF v_tournament_id IS NULL THEN
    RETURN NULL;
  END IF;

  -- Deferred triggers fire at COMMIT after every row is written, so one call
  -- per tournament per transaction sees the whole batch.
  v_flag := 'ca_instant_pay.t' || replace(v_tournament_id::text, '-', '');
  IF current_setting(v_flag, true) = 'done' THEN
    RETURN NULL;
  END IF;
  PERFORM set_config(v_flag, 'done', true);

  /* A DEADLOCK IS NEVER RETRIED HERE (2026-10-22). Measured at 06:11:38 UTC:
     every retry of a deadlocked payment deadlocked again, four times, 1 s
     each, because the other member of the cycle waits on a lock this
     transaction holds at top level (its tournaments row, or its hand
     settlement's shared tournament lane), which no subtransaction can give
     back. Retrying only held the hand commit four seconds longer. The partner
     proceeds the moment this transaction commits; a partner that is another
     bust's payer reads the committed bust and pays it, and otherwise the next
     bust or the terminal settlement does. A lock timeout or serialization
     failure is not a cycle, so those still retry. */
  LOOP
    v_attempt := v_attempt + 1;
    BEGIN
      v_result := public.fn_ca_pay_tournament_finishers_now(v_tournament_id);
      EXIT;
    EXCEPTION WHEN OTHERS THEN
      GET STACKED DIAGNOSTICS v_state = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
      v_result := jsonb_build_object('ok', false, 'sqlstate', v_state,
                                     'error', v_message, 'attempts', v_attempt);
      EXIT WHEN v_state NOT IN ('55P03', '40001') OR v_attempt >= 4;
      PERFORM pg_sleep(0.05 * v_attempt);
    END;
  END LOOP;

  IF COALESCE((v_result->>'ok')::boolean, false) IS NOT TRUE THEN
    -- The bust stays recorded and the terminal settlement still pays the
    -- place; this says, once per event, that it was not paid at the bust.
    INSERT INTO public.financial_alerts(severity, source, message, context)
    SELECT 'warning', 'tournament.real_time_payout_refused',
           'A finisher was not paid at the moment of the bust; the terminal settlement will pay the place.',
           jsonb_build_object('tournament_id', v_tournament_id, 'result', v_result)
     WHERE NOT EXISTS (
       SELECT 1 FROM public.financial_alerts fa
        WHERE fa.source = 'tournament.real_time_payout_refused'
          AND NOT fa.resolved
          AND fa.context->>'tournament_id' = v_tournament_id::text);
  END IF;
  RETURN NULL;
END;

DECLARE v_journal uuid; v_sum numeric; v_n integer; v_declared integer; v_debit bigint; v_credit bigint;
BEGIN
  IF TG_TABLE_NAME = 'trivia_ledger_journals' THEN
    v_journal := NEW.id;
  ELSE
    v_journal := NEW.journal_id;
  END IF;
  SELECT COALESCE(sum(l.amount), 0), count(*),
         COALESCE(sum(-l.amount) FILTER (WHERE l.amount < 0), 0), COALESCE(sum(l.amount) FILTER (WHERE l.amount > 0), 0)
    INTO v_sum, v_n, v_debit, v_credit
    FROM public.trivia_ledger_lines l WHERE l.journal_id = v_journal;
  SELECT j.line_count INTO v_declared FROM public.trivia_ledger_journals j
   WHERE j.id = v_journal AND j.total_debit = v_debit AND j.total_credit = v_credit;
  IF v_sum <> 0 OR v_n < 2 OR v_declared IS NULL OR v_n <> v_declared THEN
    RAISE EXCEPTION 'trivia ledger: journal % does not balance (sum %, lines %, declared %)', v_journal, v_sum, v_n, v_declared
      USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END

BEGIN
  IF TG_OP = 'DELETE' THEN
